use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::aap::caps::state_rw;
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Approved extension: record this call's input in the shared store.
        state_rw::put("last-input", &feed_url);

        // Clock: read the current wall-clock time.
        let seconds = wall_clock::now().seconds;

        // HTTP: one fetch. A transport failure is a value, not a trap, so a
        // feed that is down reports zero characters fetched. A host outside
        // the allowlist still traps at the boundary.
        let fetched: u32 = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        // Notifier: report the heartbeat to the digest channel.
        let message = format!(
            "heartbeat at {}s: fetched {} characters from {}",
            seconds, fetched, feed_url
        );
        let notified = notifier::notify(&message);

        // Contract: `ensures notified == true`. If the channel refuses, fail
        // this run instead of returning a report that breaks the contract.
        if !notified {
            panic!("notification was not accepted by the digest channel");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
